s":["intent"],"status":"unsupported"}],"outcome":"unsupported","resolved_dependencies":[],"resource_usage":[],"schema_version":"biocompiler.component_link_result.v0.3"}}]|cases} |> Json.array
let case name = List.find (fun value -> text "name" value = name) literals
let decode value = Composition.of_json (field "request" value), Component_registry.of_json (field "registry" value)
let run ?parent ?limits value = let request,registry = decode value in K.check ?parent ?limits ~request ~registry ()
let () =
  if Array.length Sys.argv <> 1 then failwith "test_composition_check accepts no arguments";
  require (List.length literals = 33) "Incomplete composition literal inventory";
  List.iter (fun value ->
    let name = text "name" value and request,registry = decode value in
    let actual = K.check ~request ~registry () in
    equal name (E.Result.to_json actual) (field "result" value);
    equal (name ^ "/dependencies") (E.Dependencies.to_json (K.dependencies ~request ~registry ()))
      (field "dependencies" (field "result" value));
    require (K.replay ~expected_request:request ~registry actual ()) (name ^ ": current fresh replay failed")) literals;
  let peak name = match E.Result.resource_usage (run (case name)) with [value] -> E.Resource_usage.peak_reservation value | _ -> assert false in
  require (peak "decimal_exact" = Some (Runtime_number.Real 0.3)) "Three exact decimal tenths did not publish binary64 0.3";
  require (peak "reusable" = Some (Runtime_number.Integer (Z.of_int 4))) "Half-open finite reusable end did not release demand";
  require (peak "consumed" = Some (Runtime_number.Integer (Z.of_int 8))) "Consumed resources were incorrectly released";
  require (peak "finite_reporting_overflow" = None) "Unrepresentable exact resource peak was published as finite";
  let ordered = E.Result.diagnostics (run (case "deterministic_unknown_groups"))
    |> List.map (fun item -> E.Link_diagnostic.code item,E.Link_diagnostic.instance_id item) in
  require (ordered = ["unknown_dependency_binding",Some "a";"unknown_dependency_binding",Some "b";
      "unknown_resource_binding",Some "a";"unknown_resource_binding",Some "b"])
    "Documented native set-difference diagnostic order changed";
  let request,registry = decode (case "decimal_exact") in
  let actual,usage = K.check_with_usage ~request ~registry () in
  require (usage.work > 0 && usage.retained_items > 0) "Composition accounting was not exercised";
  let parent maximum = W.create ~profile:"literal.composition.parent" ~error_code:"literal_composition_parent" ~maximum () in
  let exact = parent usage.work in
  equal "exact shared work" (E.Result.to_json actual) (E.Result.to_json (K.check ~parent:exact ~request ~registry ()));
  require (W.remaining exact = 0) "Shared composition work was not consumed exactly";
  rejected "literal_composition_parent" (fun () -> K.check ~parent:(parent (usage.work - 1)) ~request ~registry ());
  let repeated = parent (2 * usage.work) in ignore (K.check ~parent:repeated ~request ~registry ());
  ignore (K.check ~parent:repeated ~request ~registry ()); require (W.remaining repeated = 0) "Repeated checks reset the parent allowance";
  rejected "literal_composition_parent" (fun () -> K.check ~parent:repeated ~request ~registry ());
  let replay_parent = parent 50_000_000 in
  require (K.replay ~parent:replay_parent ~expected_request:request ~registry actual ()) "Fresh budgeted replay rejected its report";
  let replay_work = 50_000_000 - W.remaining replay_parent in
  require (replay_work > usage.work) "Replay omitted historical/comparison traversal work";
  let exact_replay = parent replay_work in
  require (K.replay ~parent:exact_replay ~expected_request:request ~registry actual () && W.remaining exact_replay = 0)
    "Replay did not consume its exact cumulative allowance";
  rejected "literal_composition_parent" (fun () -> K.replay ~parent:(parent (replay_work - 1)) ~expected_request:request ~registry actual ());
  require (K.replay ~limits:(K.make_limits ~max_work:replay_work ()) ~expected_request:request ~registry actual ())
    "Replay exact local work boundary changed";
  rejected "composition_work_limit" (fun () -> K.replay ~limits:(K.make_limits ~max_work:(replay_work - 1) ()) ~expected_request:request ~registry actual ());
  equal "exact item bound" (E.Result.to_json actual)
    (E.Result.to_json (K.check ~limits:(K.make_limits ~max_items:usage.retained_items ()) ~request ~registry ()));
  rejected "composition_item_limit" (fun () -> K.check ~limits:(K.make_limits ~max_items:(usage.retained_items - 1) ()) ~request ~registry ());
  let input_size = String.length (Canonical.encode (Json.Object ["request",Composition.to_json request;"registry",Component_registry.to_json registry])) in
  ignore (K.check ~limits:(K.make_limits ~max_input_bytes:input_size ()) ~request ~registry ());
  rejected "composition_input_limit" (fun () -> K.check ~limits:(K.make_limits ~max_input_bytes:(input_size - 1) ()) ~request ~registry ());
  rejected "composition_work_limit" (fun () -> K.check ~limits:(K.make_limits ~max_work:1 ()) ~request ~registry ());
  rejected "composition_report_limit" (fun () -> K.check ~limits:(K.make_limits ~max_report_bytes:1 ()) ~request ~registry ());
  rejected "composition_report_limit" (fun () -> K.check ~limits:(K.make_limits ~max_report_nodes:1 ()) ~request ~registry ());
  rejected "composition_rational_limit" (fun () -> K.check ~limits:(K.make_limits ~max_rational_bits:1 ()) ~request ~registry ());
  rejected "composition_limits" (fun () -> K.make_limits ~max_rational_bits:8193 ());
  let forged = E.Result.make ~outcome:E.Pass ~dependencies:(E.Result.dependencies actual)
      ~checked_requirement_ids:["forged"] ~resource_usage:(E.Result.resource_usage actual) () in
  require (not (K.replay ~expected_request:request ~registry forged ())) "An identity-only or partial receipt replay was accepted";
  (* A supported-only coordinate inventory still requires both association-list
     scans in the shared algebra. Charge it before starting the quadratic work. *)
  let replace key value raw = Json.Object ((key,value) :: List.remove_assoc key (Json.object_fields raw)) in
  let base_request,base_registry = decode (case "linked") in
  let component = List.find (fun value -> Component.id value = "source") (Component_registry.components base_registry) in
  let domain = Component_contract.Operating_domain.to_json (Component.supported_domain component) in
  let value = snd (List.hd (Json.object_fields (field "constraints" domain))) in
  let coordinates = List.init 3000 (fun index -> Printf.sprintf "coordinate_%04d" index,value) in
  let component = Component.of_json (replace "supported_domain" (replace "constraints" (Json.Object coordinates) domain) (Component.to_json component)) in
  let large_registry = Component_registry.make ~id:"supported-only" ~version:"1" ~components:[component] in
  let lock = Component_registry.lock large_registry ["a",component] in
  let instance = Composition.Instance.make ~id:"a" ~component:(List.hd (Component_registry.Lock.components lock))
      ~required_domain:(Component_contract.Operating_domain.make []) ~requirement_ids:["intent"] () in
  let large_request = Composition.make ~target:(Composition.target base_request) ~registry_lock:lock
      ~instances:[instance] ~requirement_ids:["intent"] () in
  rejected "composition_work_limit" (fun () -> K.check ~request:large_request ~registry:large_registry ());
  let restored = K.check ~request ~registry () in equal "failed checks have no cross-session state" (E.Result.to_json actual) (E.Result.to_json restored);
  Printf.printf "composition check: 33 complete independently checked results, exact decimal and lifecycle semantics, ordered diagnostics and %d exact identity/resource assertions passed\n%!" !count
